    differentiation: {
      easy: '느낌 눈금에 처음부터 이름이 보이고, 까닭 고르기에서 틀린 카드를 담으면 까닭을 알려 줘요.',
      base: '스스로 눈금과 까닭을 고른 뒤 확인해요.',
      challenge: '작품이 바뀐다는 식의 그럴듯한 까닭 카드가 더 섞여 있어요.',
    },
    teacherNotes: '자주 보이는 어려움: ① 느낌 눈금을 친구와 같게 맞추려 한다 → 정답이 없음을 처음에 한 번 더 말해 준다. ② 느낌이 다른 친구를 틀렸다고 여긴다 → 까닭 세 가지(경험·기분·좋아하는 것)를 칠판에 적어 둔다. 느낌 눈금은 정답이 없어 교사 화면에서 분포만 본다. 카드 속 작품은 모두 가상 사례다.',
