    flow: '앞의 열두 차시는 내 감상을 말로 풀고 존중하는 방법을 쌓습니다. 1~4차시는 작품을 보고 한 말을 보이는 것·느낀 점·떠오른 것으로 나누고 자세한 말로 바꾸며 느낌이 사람마다 달라지는 까닭을 찾고, 5~8차시는 따뜻한 색·되풀이·밝고 어두운 색·따라 만들기로 느낌과 관찰을 색종이로 나타냅니다. 9~12차시는 눈에 띈 곳·느낌·까닭을 이은 감상 문장을 만들고 친구의 다른 감상에 존중하는 말로 답하며 처음 감상을 고쳐 씁니다. 뒤의 열한 차시는 같은 감상을 전시와 행사로 넓혀, 13~16차시에서 전시를 만드는 사람·전시 종류·포스터 읽기·전시장 약속을 배웁니다. 17~20차시는 안내판·전시 순서·설명 카드·초대장을 직접 꾸미고, 21~23차시는 소감을 말하고 방명록과 제안을 고르며 단원 전체를 스스로 돌아봅니다.',
